"use client";

/**
 * Item. The row every list is made of: something to recognise it by
 * (an Avatar, an icon), a title and a line under it, and what trails it (a
 * time, a count, a control). Member lists, file lists, notifications,
 * settings rows. Consecutive Items are ruled by a hairline.
 *
 * `href` or `onClick` makes the row one target (the title is the link,
 * stretched over the row), like an interactive Card.
 *
 * `swipeActions` sit behind the row: swipe it toward the start and they
 * come into view, each a real button. Swipe past the last and let go, and the
 * row springs to hold them open; tap elsewhere or swipe back and it closes.
 * They are never only a gesture: Tab reaches each one, and focusing one
 * slides the row open the same way.
 *
 * Closed: slots are props, `size` is the padding step.
 */
import {
  useCallback,
  useEffect,
  useRef,
  type MouseEvent,
  type MouseEventHandler,
  type PointerEvent,
  type ReactNode,
} from "react";
import { createSpring, type Spring } from "echo-ui-core/tactile";
import { useSoundOptional } from "echo-ui-core/sound";
import "./item.css";

export interface ItemAction {
  /** The button's words. Say what it does: "Archive", "Delete file". */
  label: string;
  onSelect: () => void;
}

export interface ItemProps {
  title: ReactNode;
  /** A line under the title. */
  description?: ReactNode;
  /** What you recognise it by, at the start: an Avatar, an icon, or one small control (a done Checkbox), which stays its own target. */
  media?: ReactNode;
  /** What trails it at the end: a time, a CountBadge, a Switch. */
  trailing?: ReactNode;
  /** The whole row goes here. */
  href?: string;
  /** The whole row does this. */
  onClick?: MouseEventHandler<HTMLElement>;
  /** Actions behind the row, revealed by a swipe or by Tab. */
  swipeActions?: ItemAction[];
  /** `sm` for dense lists, `md` (default). */
  size?: "sm" | "md";
  /** `li` inside a list (`<Stack as="ul">`), `div` otherwise. Default `div`. */
  as?: "div" | "li";
}

const settle = { duration: 0.42, bounce: 0.18 };

export function Item({
  title,
  description,
  media,
  trailing,
  href,
  onClick,
  swipeActions,
  size = "md",
  as: As = "div",
}: ItemProps) {
  const sound = useSoundOptional();
  const surface = useRef<HTMLDivElement>(null);
  const tray = useRef<HTMLDivElement>(null);
  const spring = useRef<Spring | null>(null);
  const openRef = useRef(false);
  const hasActions = !!swipeActions?.length;
  const interactive = href !== undefined || onClick !== undefined;

  const reduced = () => typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  // Toward the start: left in left-to-right, right in right-to-left.
  const dir = () => (surface.current && getComputedStyle(surface.current).direction === "rtl" ? 1 : -1);
  const width = () => tray.current?.offsetWidth ?? 0;

  useEffect(() => {
    const el = surface.current;
    if (!el || !hasActions) return;
    const row = el.parentElement!;
    spring.current = createSpring(0, settle, (x) => {
      el.style.translate = Math.abs(x) < 0.3 ? "" : `${x.toFixed(1)}px 0`;
      // The tray shows only in the strip the row has slid away from.
      row.style.setProperty("--item-reveal", `${Math.abs(x).toFixed(1)}px`);
    });
    // An action focused before this ran (a fast Tab while the page was still
    // hydrating, focus restored by the browser) opens the row now.
    if (tray.current?.contains(document.activeElement)) {
      openRef.current = true;
      spring.current.set(dir() * width());
    }
    return () => spring.current?.stop();
  }, [hasActions]);

  const moveTo = useCallback((open: boolean, velocity = 0) => {
    openRef.current = open;
    const to = open ? dir() * width() : 0;
    if (reduced()) spring.current?.set(to);
    else spring.current?.to(to, { config: settle, velocity });
  }, []);

  // A swipe: follows the finger (rubber-banding past the tray), then holds
  // open or springs shut depending on how far and how fast it went.
  const drag = useRef<{ x: number; y: number; base: number; t: number; lx: number; v: number; sideways: boolean | null } | null>(null);
  const onPointerDown = (e: PointerEvent<HTMLDivElement>) => {
    if (!hasActions || e.button !== 0) return;
    drag.current = {
      x: e.clientX,
      y: e.clientY,
      base: spring.current?.value ?? 0,
      t: performance.now(),
      lx: e.clientX,
      v: 0,
      sideways: null,
    };
  };
  const onPointerMove = (e: PointerEvent<HTMLDivElement>) => {
    const d = drag.current;
    if (!d) return;
    const dx = e.clientX - d.x;
    const dy = e.clientY - d.y;
    if (d.sideways === null && Math.hypot(dx, dy) > 6) {
      d.sideways = Math.abs(dx) > Math.abs(dy);
      if (d.sideways) e.currentTarget.setPointerCapture(e.pointerId);
    }
    if (!d.sideways) return;
    const now = performance.now();
    d.v = d.v * 0.6 + ((e.clientX - d.lx) / Math.max(1, now - d.t)) * 1000 * 0.4;
    d.t = now;
    d.lx = e.clientX;
    const max = width();
    let x = d.base + dx;
    const open = dir() * max;
    // Free between shut and open; past either, it gives less and less.
    const lo = Math.min(0, open);
    const hi = Math.max(0, open);
    if (x < lo) x = lo - Math.sqrt(lo - x) * 3;
    if (x > hi) x = hi + Math.sqrt(x - hi) * 3;
    spring.current?.set(x);
  };
  const onPointerUp = () => {
    const d = drag.current;
    drag.current = null;
    if (!d?.sideways) return;
    const x = spring.current?.value ?? 0;
    const flung = d.v * dir() > 500;
    const shut = d.v * dir() < -500;
    const open = !shut && (flung || Math.abs(x) > width() / 2);
    if (open !== openRef.current) sound?.play("tap");
    moveTo(open, d.v);
  };
  // A swipe that became a drag isn't also a click on the row.
  const onClickCapture = (e: MouseEvent) => {
    if (Math.abs(spring.current?.value ?? 0) > 4 && !openRef.current) e.stopPropagation();
  };

  // Closes when focus or a tap goes elsewhere.
  const root = useRef<HTMLElement | null>(null);
  useEffect(() => {
    if (!hasActions) return;
    const away = (e: Event) => {
      if (openRef.current && root.current && !root.current.contains(e.target as Node)) moveTo(false);
    };
    document.addEventListener("pointerdown", away);
    document.addEventListener("focusin", away);
    return () => {
      document.removeEventListener("pointerdown", away);
      document.removeEventListener("focusin", away);
    };
  }, [hasActions, moveTo]);

  const name = !interactive ? (
    title
  ) : href !== undefined ? (
    <a className="echo-item__link" href={href} onClick={onClick}>
      {title}
    </a>
  ) : (
    <button type="button" className="echo-item__link" onClick={onClick}>
      {title}
    </button>
  );

  return (
    <As
      ref={(node: HTMLElement | null) => {
        root.current = node;
      }}
      className="echo-item"
      data-size={size}
      data-interactive={interactive ? "" : undefined}
    >
      {hasActions ? (
        <div ref={tray} className="echo-item__tray">
          {swipeActions!.map((a) => (
            <button
              key={a.label}
              type="button"
              className="echo-item__action"
              onFocus={() => moveTo(true)}
              onClick={() => {
                sound?.play("tap");
                a.onSelect();
                moveTo(false);
              }}
            >
              {a.label}
            </button>
          ))}
        </div>
      ) : null}
      <div
        ref={surface}
        className="echo-item__surface"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
        onClickCapture={onClickCapture}
      >
        {media ? <div className="echo-item__media">{media}</div> : null}
        <div className="echo-item__text">
          <span className="echo-item__title">{name}</span>
          {description ? <span className="echo-item__description">{description}</span> : null}
        </div>
        {trailing ? <div className="echo-item__trailing">{trailing}</div> : null}
      </div>
    </As>
  );
}

/**
 * Item. A ruled row: media, title and description, trailing content. The
 * surface slides over a tray of actions when swiped. Composes var(--echo-*).
 */
.echo-item {
  --item-py: var(--echo-space-7);
  --item-px: var(--echo-space-3);
  position: relative;
  display: block;
  overflow: hidden;
  list-style: none;
  min-width: 0;
}
.echo-item[data-size="sm"] {
  --item-py: var(--echo-space-4);
}
.echo-item + .echo-item {
  border-block-start: var(--echo-border-hairline, 1px) solid var(--echo-seam);
}
.echo-item__surface {
  position: relative;
  z-index: var(--echo-z-raised, 1);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--echo-space-7);
  padding: var(--item-py) var(--item-px);
  touch-action: pan-y;
}
.echo-item__surface:not(:has(.echo-item__media)) {
  grid-template-columns: minmax(0, 1fr) auto;
}
.echo-item__media {
  display: flex;
  align-items: center;
}
/* A control at the start (a done box) is its own target, above the row's
   stretched link, like trailing controls. Media that is only a picture stays
   under it, so pressing an avatar still opens the row. */
.echo-item__media:has(button, input, a, [role="checkbox"], [role="switch"]) {
  position: relative;
  z-index: var(--echo-z-top, 2);
}
.echo-item__text {
  display: grid;
  gap: var(--echo-space-1);
  min-width: 0;
}
.echo-item__title {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--echo-text-md);
  font-weight: var(--echo-weight-semibold, 600);
  color: var(--echo-text);
}
.echo-item__description {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}
.echo-item__trailing {
  display: flex;
  align-items: center;
  gap: var(--echo-space-4);
  position: relative;
  z-index: var(--echo-z-top, 2);
  font-size: var(--echo-text-sm);
  color: var(--echo-text-dim);
}

/* Interactive: the title is the link, stretched over the row. */
.echo-item__link {
  all: unset;
  cursor: pointer;
}
.echo-item__link::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: var(--echo-z-raised, 1);
}
.echo-item[data-interactive] .echo-item__surface {
  transition: background var(--echo-duration-tick) ease;
}
@media (hover: hover) {
  .echo-item[data-interactive] .echo-item__surface:hover {
    background: color-mix(in oklab, var(--echo-cap) 28%, transparent);
  }
}
.echo-item:has(.echo-item__link:focus-visible) .echo-item__surface {
  box-shadow: var(--echo-shadow-ring-inset, inset 0 0 0 2px var(--echo-accent-ink, var(--echo-accent-glow)));
}

/* The tray: behind the row at its end, the actions as small neutral caps. */
.echo-item__tray {
  position: absolute;
  inset-block: 0;
  inset-inline-end: 0;
  display: flex;
  align-items: center;
  gap: var(--echo-space-3);
  padding-inline: var(--echo-space-4);
  background: var(--echo-well);
  box-shadow: inset 0 2px 5px color-mix(in oklab, var(--echo-cast-ink, black) calc(0.6 * var(--echo-shade, 1) * 100%), transparent);
  /* Only the strip the row has slid away from: the row itself stays on
     whatever ground it sits on. */
  clip-path: inset(0 0 0 calc(100% - var(--item-reveal, 0px)));
}
.echo-item__tray:dir(rtl) {
  clip-path: inset(0 calc(100% - var(--item-reveal, 0px)) 0 0);
}
.echo-item__action {
  box-sizing: border-box;
  min-height: var(--echo-control-compact);
  padding: 0 var(--echo-space-6);
  border: 0;
  border-radius: var(--echo-radius-md);
  cursor: pointer;
  color: var(--echo-text);
  font-family: var(--echo-font-machine, ui-sans-serif, system-ui, sans-serif);
  font-size: var(--echo-text-2xs);
  font-weight: var(--echo-weight-bold, 700);
  letter-spacing: var(--echo-tracking-wider, 0.12em);
  text-transform: uppercase;
  background: linear-gradient(180deg, var(--echo-cap-highlight) 0%, var(--echo-cap) 55%, var(--echo-cap-shadow) 100%);
  box-shadow: var(
    --echo-shadow-key,
    inset 0 1px 0 rgb(255 255 255 / calc(0.3 * var(--echo-gloss, 1))),
    0 2px 0 var(--echo-seam)
  );
}
.echo-item__action:focus-visible {
  outline: 2px solid transparent;
  box-shadow: var(
    --echo-shadow-ring,
    0 0 0 2px var(--echo-surface),
    0 0 0 4px var(--echo-accent-ink, var(--echo-accent-glow))
  );
}
.echo-item__action:active {
  transform: translateY(1px);
}
@media (pointer: coarse) {
  .echo-item__action {
    min-height: 44px;
  }
}
@media (forced-colors: active) {
  .echo-item + .echo-item {
    border-color: CanvasText;
  }
  .echo-item__action {
    border: var(--echo-border-hairline, 1px) solid ButtonText;
  }
  .echo-item:has(.echo-item__link:focus-visible) .echo-item__surface {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
